export function parseCsvRow(row: string): string[] {
  const results: string[] = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < row.length; i++) {
    const char = row[i];
    if (char === '"') {
      if (inQuotes && row[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      results.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  results.push(current);
  return results;
}
